-- Create "action_log" table
CREATE TABLE `action_log` (`id` int unsigned NOT NULL AUTO_INCREMENT, `created_at` datetime NOT NULL, `type` varchar(64) NOT NULL, `action_group` varchar(64) NOT NULL, `actor_id` int unsigned NULL, `actor_name` varchar(255) NOT NULL DEFAULT '', `ip` varchar(64) NOT NULL DEFAULT '', `object_kind` varchar(32) NOT NULL DEFAULT '', `object_id` varchar(64) NOT NULL DEFAULT '', `object_label` varchar(512) NOT NULL DEFAULT '', `object_type` varchar(255) NOT NULL DEFAULT '', `object_url` varchar(512) NOT NULL DEFAULT '', `changes` text NOT NULL, PRIMARY KEY (`id`), INDEX `action_log_created_at` (`created_at`), INDEX `action_log_group_created_at` (`action_group`, `created_at`), INDEX `action_log_actor_created_at` (`actor_id`, `created_at`), INDEX `action_log_object` (`object_kind`, `object_id`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "action_log_settings" table
CREATE TABLE `action_log_settings` (`id` int unsigned NOT NULL AUTO_INCREMENT, `keep_days` int NOT NULL DEFAULT 90, `log_ip` bool NOT NULL DEFAULT true, `groups_off` varchar(1024) NOT NULL DEFAULT '', PRIMARY KEY (`id`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
